def copy_locators_to_observations(apps, schema_editor):
    """
    Turn the locator stored on each payload into an observation without a sensor.

    Before this migration GreedyBear could only poll a single payload server and
    did not know which sensor it belonged to. Payloads without a locator (hash-only
    stubs) were never seen on a payload server and get no observation.
    """
    schema_editor.execute(
        """
        INSERT INTO greedybear_payloadobservation (payload_id, locator, mtime)
        SELECT id, locator, mtime FROM greedybear_honeypotpayload
        WHERE locator <> '';
        """
    )


def copy_observations_to_locators(apps, schema_editor):
    """
    Put one locator back on each payload, preferring the observation without a sensor.
    """
    schema_editor.execute(
        """
        UPDATE greedybear_honeypotpayload AS payload
        SET locator = observation.locator, mtime = observation.mtime
        FROM (
            SELECT DISTINCT ON (payload_id) payload_id, locator, mtime
            FROM greedybear_payloadobservation
            ORDER BY payload_id, sensor_id NULLS FIRST
        ) AS observation
        WHERE observation.payload_id = payload.id;
        """
    )


